def test_transform_final(grid, inp):
    """Final strategy:
    1. Fill 8 bboxes with 8 (irrespective of cell values inside)
    2. Fill 2 bboxes with 2 (irrespective of cell values inside)
    3. 6's that are in bbox become 3 (noise), 6's NOT in bbox stay 6
    4. Fill remaining noise cells with 3
    5. Expand 6: any noise cell adjacent to preserved 6 becomes 6
    """
