            for c in range(min_c, max_c + 1):
                g[r][c] = 8

    # Step 2: Fill 2 bboxes
    for comp in comps_2:
        min_r, max_r, min_c, max_c = get_bbox(comp)
        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                g[r][c] = 2

    # Step 3: 6's in bbox become 3, 6's not in bbox stay 6
    for r in range(rows):
        for c in range(cols):
            if inp[r][c] == 6:
                if is_6_in_bbox(r, c):
                    g[r][c] = 3
                else:
                    g[r][c] = 6

    # Step 4: Fill remaining noise
    for r in range(rows):
        for c in range(cols):
            if is_noise(r, c) and g[r][c] == inp[r][c]:
                g[r][c] = 3

    # Step 5: 6-expansion: noise adjacent to preserved 6 -> 6
    for r in range(rows):
        for c in range(cols):
            if is_noise(r, c) and g[r][c] == 3:
                # Check if adjacent to any original 6
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if inp[nr][nc] == 6:
                            if not is_6_in_bbox(nr, nc):  # Only expand from preserved 6
                                g[r][c] = 6
                                break

    return g

